#[path="../../search-lab/src/analyzer.rs"]mod analyzer;
#[path="../../search-lab/src/fts.rs"]mod fts;
use analyzer::Analyzer;
use rusqlite::{Connection,params};
use serde::Deserialize;
use serde_json::json;
use std::{path::Path,time::Instant};
use tantivy::{Index,IndexReader,IndexWriter,Term,doc,collector::TopDocs,query::{BooleanQuery,Occur,Query,TermQuery},schema::*,tokenizer::{Tokenizer,TokenStream,Token}};
#[derive(Clone,Deserialize)]struct Doc {id:u64,key:String,title:String,body:String}
#[derive(Deserialize)]struct Question{text:String}
#[derive(Deserialize)]struct Corpus{docs:Vec<Doc>,queries:Vec<Question>}
fn us(t:Instant)->u64{t.elapsed().as_micros()as u64}
fn stats(v:&mut[u64])->serde_json::Value{v.sort_unstable();let p=|f:f64|v[((v.len()-1)as f64*f).ceil()as usize];json!({"n":v.len(),"p50_us":p(0.5),"p95_us":p(0.95),"p99_us":p(0.99),"max_us":p(1.),"sum_us":v.iter().sum::<u64>()})}
fn memory()->serde_json::Value{let s=std::fs::read_to_string("/proc/self/status").unwrap();let get=|k:&str|s.lines().find(|l|l.starts_with(k)).unwrap().split_whitespace().nth(1).unwrap().parse::<u64>().unwrap();json!({"rss_kib":get("VmRSS:"),"hwm_kib":get("VmHWM:")})}
fn cpu()->f64{unsafe{let mut r:libc::rusage=std::mem::zeroed();assert_eq!(libc::getrusage(libc::RUSAGE_SELF,&mut r),0);(r.ru_utime.tv_sec+r.ru_stime.tv_sec)as f64+(r.ru_utime.tv_usec+r.ru_stime.tv_usec)as f64/1e6}}
fn disk(p:&Path)->u64{if p.is_file(){p.metadata().unwrap().len()}else if p.is_dir(){std::fs::read_dir(p).unwrap().map(|e|disk(&e.unwrap().path())).sum()}else{0}}
#[derive(Clone)]struct Shared(Analyzer);
struct Stream{tokens:std::vec::IntoIter<analyzer::Token>,token:Token}
impl Tokenizer for Shared{type TokenStream<'a>=Stream;fn token_stream<'a>(&'a mut self,text:&'a str)->Stream{Stream{tokens:self.0.tokens(text).into_iter(),token:Token::default()}}}
impl TokenStream for Stream{fn advance(&mut self)->bool{if let Some(t)=self.tokens.next(){self.token=Token{text:t.text,offset_from:t.start,offset_to:t.end,position:t.position,position_length:1};true}else{false}}fn token(&self)->&Token{&self.token}fn token_mut(&mut self)->&mut Token{&mut self.token}}
struct Owned{index:Index,writer:IndexWriter,reader:IndexReader,id:Field,key:Field,title:Field,body:Field,analyzer:Analyzer}
impl Owned{
fn new(path:&str)->Self{std::fs::create_dir(path).unwrap();let mut schema=Schema::builder();let id=schema.add_u64_field("id",FAST|STORED);let key=schema.add_text_field("key",STRING|STORED);let options=TextOptions::default().set_stored().set_indexing_options(TextFieldIndexing::default().set_tokenizer("shared").set_index_option(IndexRecordOption::WithFreqsAndPositions));let title=schema.add_text_field("title",options.clone());let body=schema.add_text_field("body",options);let index=Index::create_in_dir(path,schema.build()).unwrap();let analyzer=Analyzer::new("auto");index.tokenizers().register("shared",Shared(analyzer.clone()));let writer=index.writer_with_num_threads(1,32_000_000).unwrap();let reader=index.reader().unwrap();Self{index,writer,reader,id,key,title,body,analyzer}}
fn set(&mut self,d:&Doc){self.writer.delete_term(Term::from_field_text(self.key,&d.key));self.writer.add_document(doc!(self.id=>d.id,self.key=>d.key.as_str(),self.title=>d.title.as_str(),self.body=>d.body.as_str())).unwrap();}
fn delete(&mut self,key:&str){self.writer.delete_term(Term::from_field_text(self.key,key));}
fn commit(&mut self){self.writer.commit().unwrap();self.reader.reload().unwrap();}
fn query(&self,text:&str)->(Vec<u64>,usize){let mut terms=std::collections::BTreeSet::new();for w in Analyzer::new("icu").tokens(text){for t in self.analyzer.query_tokens(&text[w.start..w.end]){terms.insert(t.text);}}let qs:Vec<(Occur,Box<dyn Query>)>=terms.into_iter().flat_map(|t|[self.title,self.body].map(move|f|(Occur::Should,Box::new(TermQuery::new(Term::from_field_text(f,&t),IndexRecordOption::WithFreqsAndPositions))as Box<dyn Query>))).collect();let q=BooleanQuery::new(qs);let s=self.reader.searcher();let mut ids=vec![];let mut bytes=0;for(_,addr)in s.search(&q,&TopDocs::with_limit(10).order_by_score()).unwrap(){let d:TantivyDocument=s.doc(addr).unwrap();ids.push(d.get_first(self.id).unwrap().as_u64().unwrap());for f in [self.key,self.title,self.body]{bytes+=d.get_first(f).unwrap().as_str().unwrap().len();}}(ids,bytes)}
fn check(&self,n:u64){assert_eq!(self.reader.searcher().num_docs(),n);let meta=self.index.load_metas().unwrap();assert!(meta.opstamp>0);}
}
fn sql(path:&str)->Connection{let c=Connection::open(path).unwrap();fts::register(&c,"auto");c.execute_batch("pragma journal_mode=wal;pragma synchronous=FULL;pragma cache_size=-1024;pragma wal_autocheckpoint=0;pragma trusted_schema=off;create table keys(id integer primary key,key text unique not null);create virtual table docs using fts5(key unindexed,title,body,tokenize='tiny_auto_v1');").unwrap();c}
fn sql_set(c:&Connection,d:&Doc){c.prepare_cached("insert into keys(id,key)values(?1,?2)on conflict(id)do update set key=excluded.key").unwrap().execute(params![d.id as i64,d.key]).unwrap();c.prepare_cached("delete from docs where rowid=?1").unwrap().execute([d.id as i64]).unwrap();c.prepare_cached("insert into docs(rowid,key,title,body)values(?1,?2,?3,?4)").unwrap().execute(params![d.id as i64,d.key,d.title,d.body]).unwrap();}
fn sql_query(c:&Connection,text:&str)->(Vec<u64>,usize){let q=fts::query_string(text,"auto");let mut ids=vec![];let mut bytes=0;let mut st=c.prepare_cached("select rowid,key,title,body from docs where docs match ?1 order by rank limit 10").unwrap();let mut rs=st.query([q]).unwrap();while let Some(r)=rs.next().unwrap(){ids.push(r.get::<_,i64>(0).unwrap()as u64);for f in 1..4 {bytes+=r.get::<_,String>(f).unwrap().len();}}(ids,bytes)}
fn main(){let a:Vec<_>=std::env::args().skip(1).collect();let engine=&a[0];let n:usize=a[2].parse().unwrap();let idle=memory();let corpus:Corpus=serde_json::from_reader(std::fs::File::open(&a[1]).unwrap()).unwrap();let mut docs:Vec<_>=(0..n).map(|i|{let mut d=corpus.docs[i%corpus.docs.len()].clone();d.id=i as u64+1;d.key=format!("document/{i}");d}).collect();let loaded=memory();let cpu0=cpu();let path=std::env::var("BENCH_DB").unwrap();let mut sqlite=None;let mut tant=None;let t=Instant::now();if engine=="fts"{let c=sql(&path);c.execute_batch("begin immediate").unwrap();for d in &docs{sql_set(&c,d);}c.execute_batch("commit").unwrap();sqlite=Some(c);}else{let mut t=Owned::new(&path);for d in &docs{t.set(d);}t.commit();tant=Some(t);}let build_us=us(t);let build_memory=memory();let build_wal=disk(Path::new(&format!("{path}-wal")));let checkpoint=Instant::now();if let Some(c)=&sqlite{c.execute_batch("pragma wal_checkpoint(truncate)").unwrap();}let checkpoint_us=us(checkpoint);let build_disk=disk(Path::new(&path));let mut ts=vec![];let mut payload_bytes=0;let mut returned_ids=vec![];let qt=Instant::now();for q in corpus.queries.iter().take(60){let t=Instant::now();let(ids,bytes)=if let Some(c)=&sqlite{sql_query(c,&q.text)}else{tant.as_ref().unwrap().query(&q.text)};ts.push(us(t));payload_bytes+=bytes;returned_ids.push(ids);}let query_us=us(qt);let mut phases=vec![];
for batch in [1,100]{for op in ["set","delete"]{let mut times=vec![];for part in 0..(100/batch){let t=Instant::now();if let Some(c)=&sqlite{c.execute_batch("begin immediate").unwrap();}for i in 0..batch{let j=part*batch+i;if op=="set"{docs[j].title.push_str(" revised");if let Some(c)=&sqlite{sql_set(c,&docs[j]);}else{tant.as_mut().unwrap().set(&docs[j]);}}else{let d=&docs[j];if let Some(c)=&sqlite{c.prepare_cached("delete from docs where rowid=?1").unwrap().execute([d.id as i64]).unwrap();c.prepare_cached("delete from keys where id=?1").unwrap().execute([d.id as i64]).unwrap();}else{tant.as_mut().unwrap().delete(&d.key);}}}if let Some(c)=&sqlite{c.execute_batch("commit").unwrap();}else{tant.as_mut().unwrap().commit();}times.push(us(t));}let stat=stats(&mut times);phases.push(json!({"operation":op,"batch":batch,"documents":100,"transactions":100/batch,"commit_and_visibility":stat,"wal_file_bytes":disk(Path::new(&format!("{path}-wal"))),"backend_bytes":disk(Path::new(&path))}));if let Some(c)=&sqlite{c.execute_batch("pragma wal_checkpoint(truncate)").unwrap();}}
// Restore keys after each batching comparison, outside its measurements.
if let Some(c)=&sqlite{c.execute_batch("begin immediate").unwrap();for d in docs.iter().take(100){sql_set(c,d);}c.execute_batch("commit;pragma wal_checkpoint(truncate);").unwrap();}else{let t=tant.as_mut().unwrap();for d in docs.iter().take(100){t.set(d);}t.commit();}}
let validate=Instant::now();if let Some(c)=&sqlite{c.execute("insert into docs(docs)values('integrity-check')",[]).unwrap();let count:i64=c.query_row("select count(*)from docs",[],|r|r.get(0)).unwrap();assert_eq!(count,n as i64);let bare=Connection::open(&path).unwrap();fts::register(&bare,"auto");assert_eq!(sql_query(c,"SQLite"),sql_query(&bare,"SQLite"));}else{let t=tant.as_ref().unwrap();t.check(n as u64);let i=Index::open_in_dir(&path).unwrap();i.tokenizers().register("shared",Shared(Analyzer::new("auto")));let r:IndexReader=i.reader().unwrap();assert_eq!(r.searcher().num_docs(),n as u64);}let validation_us=us(validate);println!("{}",json!({"engine":engine,"mode":"auto","rows":n,"cpu_total_s":cpu()-cpu0,"bulk_import_us":build_us,"bulk_documents_per_s":n as f64*1e6/build_us as f64,"post_import_checkpoint_us":checkpoint_us,"initial_backend_bytes":build_disk,"initial_wal_peak_bytes":build_wal,"query_top10_hydrated":stats(&mut ts),"query_per_s":60.*1e6/query_us as f64,"hydrated_bytes":payload_bytes,"returned_ids":returned_ids,"mutation_phases":phases,"final_backend_bytes":disk(Path::new(&path)),"idle_memory":idle,"loaded_memory":loaded,"build_memory":build_memory,"end_memory":memory(),"reopen_integrity_us":validation_us,"status":"pass","boundary":"One authoritative backend per standalone collection, raw fields stored and hydrated, synchronous commit/reload. Not public Core/grouped commits or SQL-table atomicity."}));}
